const Portfolio: FC = () => {
  const [active, setActive] = useState("hero");
  useEffect(() => {
    const ids = ["hero","about","experience","projects","contact"];
    const obs = ids.map(id => {
      const el = document.getElementById(id);
      if (!el) return null;
      const io = new IntersectionObserver(([e])=>{ if(e.isIntersecting) setActive(id); },{ threshold:0.3 });
      io.observe(el);
      return io;
    }).filter((o): o is IntersectionObserver => o!==null);
    return () => obs.forEach(o=>o.disconnect());
  },[]);

  return (
    <div style={{ background:T.bg0, color:T.t1, minHeight:"100vh", fontFamily:T.sans, position:"relative" }}>
      <GlobalStyles/>
      <Nav active={active}/>
      <div style={{ position:"relative", zIndex:1 }}>
        <HeroSection/>
        <AboutSection/>
        <ExperienceSection/>
        <ProjectsSection/>
        <ContactSection/>
        <Footer/>
      </div>
    </div>
  );
};

export default Portfolio;